func batchPushRefs(ctx context.Context, target string, refs []plumbing.ReferenceName) error {
	if len(refs) == 0 {
		return nil
	}
	refSpecs := make([]string, 0, len(refs))
	for _, ref := range refs {
		refSpecs = append(refSpecs, ref.String()+":"+ref.String())
