	if err != nil {
		return fmt.Errorf("push %d checkpoint refs: %w", len(refs), err)
	}
	return nil
===== PushWithOptions (git.go) =====
func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
	pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
	if err != nil {
		return PushResult{}, fmt.Errorf("resolve push target: %w", err)
	}

	args := []string{"push", "--no-verify", "--porcelain", "--progress"}
	args = append(args, opts.ExtraArgs...)
	args = append(args, pushTarget)
	args = append(args, opts.RefSpecs...)

	cmd := newCommand(ctx, args...)
	if opts.Dir != "" {
		cmd.Dir = opts.Dir
	}
	disableTerminalPrompt(cmd)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err = cmd.Run()
	result := PushResult{
		Output: stdout.String(),
		Stderr: stderr.String(),
	}
	if err != nil {
		combined := stdout.String()
		if stderr.Len() > 0 {
			if combined != "" {
				combined += "\n"
			}
			combined += stderr.String()
		}
		result.Output = combined
		return result, fmt.Errorf("git push: %w", err)
	}
	return result, nil
}

